        setCopyDocumentData((prevData) => prevData.filter((item) => item.Id !== editDocRef.Id));
        setCopyAllDocumentData((prevData) => prevData.filter((item) => item.Id !== editDocRef.Id));
    }
    else {
        getDocumentItem(docItem);
    }
    setEditdocpanel(false);
}, [getDocumentItem]);

