const getDocumentItem = (async (docitem: any) => {
    let filter = 'Id eq ' + docitem?.Id;
    let query = "Id,Title,PriorityRank,Year,Body,Item_x0020_Cover,Portfolios/Id,Portfolios/Title,File_x0020_Type,FileLeafRef,FileDirRef,ItemRank,ItemType,Url,Created,Modified,Author/Id,Author/Title,Editor/Id,Editor/Title,EncodedAbsUrl,File/Length&$expand=File,Author,Editor,Portfolios";
    const web = new Web(props?.siteUrl);
    try {
        await web.lists.getById(props?.DocumentsListID).items.select(query)
            .filter(`${filter}`)
            .getAll()
            .then((Data) => {
                if (Data?.length > 0) {
                    Data.forEach(item => {
                        if ((item?.Title == undefined || item?.Title == "") && item?.FileLeafRef != undefined) {
                            item.Title = item?.FileLeafRef;
                        }
                        if (item?.Title != undefined && item?.Title.includes(item?.File_x0020_Type)) {
                            item.Title = getUploadedFileName(item?.Title);
                        }
                        item.siteType = "sp";
                        item.Description = item?.Body;
                        item['MatchBody'] = limitTo100Words(item?.Body);
                        const fileSizeInBytes = item?.File?.Length;
                        const myfileSize = fileSizeInBytes / (1024 * 1024);
                        item.fileSize = myfileSize.toFixed(2);
                        item.FileSize = `${Math.ceil(item?.File?.Length / 1024)} KB`;
                        if (item?.Title != undefined && item?.File_x0020_Type != undefined) {
                            item.docType = item?.File_x0020_Type;
                        } else if (item?.Title != undefined && item?.itemSystemObjectType != 1) {
                            item.docType = getFileType(item?.Name);
                        }
                        if (item?.File_x0020_Type == "aspx") {
                            item.docType = "link";
                        }
                        if (item?.File_x0020_Type == "rar") {
                            item.docType = "zip";
                        }
                        if (item?.File_x0020_Type == "jpg" || item?.File_x0020_Type == "jfif") {
                            item.docType = "jpeg";
                        }
                        if (item?.File_x0020_Type == "doc") {
                            item.docType = "docx";
                        }
                        if (item?.File_x0020_Type == "eml") {
                            item.docType = "unknownFile";
                        }

                        item.CreatedDate = moment(item?.Created).format("DD/MM/YYYY");
                        item.ModifiedDate = moment(item?.Modified).format("DD/MM/YYYY");
                        props?.Alltaskuser?.forEach((element: any) => {
                            if (element?.AssingedToUserId == item?.Author?.Id) {
                                item.AuthorImage = element?.Item_x0020_Cover?.Url;
                            }
                            if (element?.AssingedToUserId == item?.Editor?.Id) {
                                item.EditorImage = element?.Item_x0020_Cover?.Url;
                            }
                        });
                    });
                    let data = documentData.filter((val) => {
                        return !Data?.some(item => item.Id === val.Id);
                    });
                    setDocumentData(prevData =>
                        prevData.map(item =>
                            item.Id === Data[0]?.Id ? { ...item, ...Data[0] } : item
                        )
                    );
                    // setAllDocumentData(data)
                    setAllDocumentData(prevData =>
                        prevData.map(item =>
                            item.Id === Data[0]?.Id ? { ...item, ...Data[0] } : item
                        )
                    );
                    // PrepareData(Data)
                    setloadedDoc(false)
                }
            });
    } catch (e) {
