// Task Profile must not whole-library getAll on navigate — that is the ~15s skeleton.
useEffect(() => {
    if (deferSubDocsUntilOpen) {
        return;
    }
    if (props?.taskpage == 'taskprogile') {
        return;
    }
    if (isRadimadeFullyReady) {
        devSuccess("When Radimadetable data (AllMasterTaskData + AllSiteTasks) is ready: Triggering document loading logic for sub-items.");
        loadAllSitesDocuments(true);
    }
}, [isRadimadeFullyReady, deferSubDocsUntilOpen]);

// Reset selections when data changes
useEffect(() => {
    setSelectedDocuments([]);
    setSelectAllMain(false);
}, [documentData]);

useEffect(() => {
    if (deferSubDocsUntilOpen) {
        // Do not wipe sub docs after the user has already expanded & loaded them.
        if (!subDocsRequestedRef.current) {
            setAllDocumentData([]);
            setCopyAllDocumentData([]);
            setsortAllDocumentData([]);
            setSelectedSubDocuments([]);
        }
        return;
    }
    if (props?.taskpage != 'taskprogile') {
        dynamicClumnConfigPrepare1();
        dynamicClumnConfigPrepare2();
        if (isRadimadeFullyReady) {
            loadAllSitesDocuments();
        } else {
            // Keep sub-relevant table empty until Radimade finishes loading.
            setAllDocumentData([]);
            setCopyAllDocumentData([]);
            setsortAllDocumentData([]);
            setSelectedSubDocuments([]);
        }
    }
    else {
        // Task Profile: getTaggeddocuments already ran on ID — do not getAll the Documents library.
    }
}, [isRadimadeFullyReady, deferSubDocsUntilOpen]);

