// otherwise the panel renders blank rather than "loading".
const isMainDocsLoading =
    docsLoading ||
    loadedDoc ||
    !(column?.length > 0);
const isSubDocsLoading = isPortfolioProfile
    ? (
        openSub && (
            subDocsLoading ||
            (shouldWaitForRadimadeData && !isRadimadeFullyReady) ||
            !(column2?.length > 0 && columnSettingConfigDatarelevant?.settingConfrigrationData != undefined)
        )
    )
    : (
        docsLoading ||
        loadedDoc ||
        shouldDelaySubRelevantBinding ||
        !(column2?.length > 0 && columnSettingConfigDatarelevant?.settingConfrigrationData != undefined)
    );

const requestDocumentsLoad = () => {
    // Same profile visit: reopen accordion must not re-hit Documents.
    if (docsRequestedRef.current) {
        return;
    }
    docsRequestedRef.current = true;
    setDocsLoading(true);
    dynamicClumnConfigPrepare1();
    dynamicClumnConfigPrepare2();
    getTaggeddocuments(props);
};

const requestSubDocumentsLoad = () => {
    if (subDocsRequestedRef.current) {
        return;
    }
    subDocsRequestedRef.current = true;
    setSubDocsLoading(true);
    dynamicClumnConfigPrepare2();
    // Child docs need the sites library + hierarchy matching (not the light tagged fetch).
    loadAllSitesDocuments(false);
};

// Portfolio Profile: load sub-item docs on first expand (after Radimade is ready when applicable).
useEffect(() => {
    if (!deferSubDocsUntilOpen || !openSub || subDocsRequestedRef.current) {
        return;
    }
    if (shouldWaitForRadimadeData && !isRadimadeFullyReady) {
        setSubDocsLoading(true);
        return;
    }
    requestSubDocumentsLoad();
}, [openSub, isRadimadeFullyReady, deferSubDocsUntilOpen, shouldWaitForRadimadeData]);

