const loadSubItemDocumentsTargeted = async () => {
    beginLoad();
    if (!stillLive()) return;

    try {
        const currentSiteUrl = props?.siteUrl;
        const masterRows: any[] = (props?.AllMasterTaskData || []).filter((row: any) =>
            !row?.siteUrl || row.siteUrl === currentSiteUrl
        );
        const taskRows: any[] = (props?.AllSiteTasks || []).filter((row: any) =>
            !row?.siteUrl || row.siteUrl === currentSiteUrl
        );
        if (masterRows?.length === 0) {
            await loadAllSitesDocuments(false);
            return;
        }

        fetchedMasterDataRef.current = masterRows;
        AllSitesAllTasksRef.current = taskRows;
        MasterDataCompare(fetchedMasterDataRef.current);

        const projectItem = ProjectDataRef.current;
        const isProjectType =
            projectItem?.Item_x0020_Type == "Sprint" ||
            projectItem?.Item_x0020_Type == "Project" ||
            projectItem?.Item_x0020_Type == "Cycle";
        const isPortfolioType =
            projectItem?.Item_x0020_Type == "Component" ||
            projectItem?.Item_x0020_Type == "SubComponent" ||
            projectItem?.Item_x0020_Type == "Feature";

        const childPortfolioIds = new Set<number>();
        const projectIds = new Set<number>();
        const smartDocIds = new Set<number>();

        const collectChildSmartDocs = (row: any) => {
            row?.SmartDocument?.forEach((doc: any) => {
                if (doc?.Id != undefined) smartDocIds.add(doc.Id);
            });
        };

        if (projectItem?.SprintRows?.length > 0) {
            projectItem.SprintRows.forEach((row: any) => {
                if (row?.Id != undefined) {
                    childPortfolioIds.add(row.Id);
                    projectIds.add(row.Id);
                }
                collectChildSmartDocs(row);
            });
        }
        if (projectItem?.CycleRows?.length > 0) {
            projectItem.CycleRows.forEach((row: any) => {
                if (row?.Id != undefined) {
                    childPortfolioIds.add(row.Id);
                    projectIds.add(row.Id);
                }
                collectChildSmartDocs(row);
            });
        }
        if (isProjectType && projectItem?.Id != undefined) {
            projectIds.add(projectItem.Id);
        }

        taskRows.forEach((task: any) => {
            const matchesProject = projectIds.has(task?.Project?.Id);
            const matchesPortfolio = isPortfolioType && (
                task?.Portfolio?.Id == projectItem?.Id ||
                childPortfolioIds.has(task?.Portfolio?.Id)
            );
            if (!matchesProject && !matchesPortfolio) return;
            task?.SmartDocument?.forEach((doc: any) => {
                if (doc?.Id != undefined) {
                    smartDocIds.add(doc.Id);
                }
            });
        });

        const idClauses: string[] = [];
        if (smartDocIds.size > 0) {
            idClauses.push(...Array.from(smartDocIds).map((id) => `Id eq ${id}`));
        }
        if (childPortfolioIds.size > 0) {
            idClauses.push(...Array.from(childPortfolioIds).map((id) => `Portfolios/Id eq ${id}`));
        }

        if (idClauses.length === 0) {
            AllDocumentDataRef.current = [];
            filterTagDoc();
            return;
        }

        const web = new Web(props?.siteUrl);
        const queryBase = "Id,Title,PriorityRank,Year,Body,Item_x0020_Cover,Portfolios/Id,Portfolios/Title,Portfolios/PortfolioStructureID,Portfolios/ItemType,File_x0020_Type,FileLeafRef,FileDirRef,ItemRank,ItemType,Url,Created,Modified,Author/Id,Author/Title,Editor/Id,Editor/Title,SmartDocumentType/Id,SmartDocumentType/Title,EncodedAbsUrl,File/Length,HHHH/Id,HHHH/Title,Shareweb/Id,Gruene/Id,ILF/Id,Gender/Id,ALAKDigital/Id&$expand=File,Author,Editor,SmartDocumentType,Portfolios,HHHH,Shareweb,Gruene,ILF,Gender,ALAKDigital";
        const chunkSize = 20;
        const docs: any[] = [];
        for (let i = 0; i < idClauses.length; i += chunkSize) {
            const chunk = idClauses.slice(i, i + chunkSize);
            const filter = `FSObjType eq 0 and (${chunk.join(" or ")})`;
            const page = await web.lists.getByTitle("Documents").items.select(queryBase).filter(filter).getAll();
            if (!stillLive()) return;
            if (page?.length) docs.push(...page);
        }

        if (!stillLive()) return;

        const uniqueDocs = (docs || [])
            .filter((item: any, index: number, self: any[]) => index === self.findIndex((x: any) => x?.Id === item?.Id))
            .filter((item: any) => includedTypes.includes((item?.docType ?? item?.File_x0020_Type)?.toLowerCase()))
            .filter((item: any) => !item?.Title?.toLowerCase?.().includes("evaluation"));

        AllDocumentDataRef.current = uniqueDocs.map((item: any) => {
            const mapped = { ...item, siteUrl: props?.siteUrl };
            if ((mapped?.Title == undefined || mapped?.Title == "") && mapped?.FileLeafRef != undefined) {
                mapped.Title = mapped?.FileLeafRef;
            }
            if (mapped?.Title != undefined && mapped?.Title.includes(mapped?.File_x0020_Type)) {
                mapped.Title = getUploadedFileName(mapped?.Title);
            }
            mapped["MatchBody"] = limitTo100Words(mapped?.Body);
            const fileSizeInBytes = mapped?.File?.Length;
            const myfileSize = fileSizeInBytes / (1024 * 1024);
            mapped.fileSize = myfileSize.toFixed(2);
            mapped.FileSize = `${Math.ceil(mapped?.File?.Length / 1024)} KB`;
            if (mapped?.Title != undefined && mapped?.File_x0020_Type != undefined) {
                mapped.docType = mapped?.File_x0020_Type;
            } else if (mapped?.Title != undefined && mapped?.itemSystemObjectType != 1) {
                mapped.docType = getFileType(mapped?.Name);
            }
            if (mapped?.File_x0020_Type == "aspx") mapped.docType = "link";
            if (mapped?.File_x0020_Type == "rar") mapped.docType = "zip";
            if (mapped?.File_x0020_Type == "jpg" || mapped?.File_x0020_Type == "jfif") mapped.docType = "jpeg";
            if (mapped?.File_x0020_Type == "doc") mapped.docType = "docx";
            if (mapped?.File_x0020_Type == "eml") mapped.docType = "unknownFile";
            mapped.CreatedDate = moment(mapped?.Created).format("DD/MM/YYYY");
            mapped.ModifiedDate = moment(mapped?.Modified).format("DD/MM/YYYY");
            applyUserImages(mapped);
            return mapped;
        });

        // Reuse existing merge/dedupe logic and state updates.
        filterTagDoc();
    } catch (e) {
        devError(e, "Oops! Something went wrong.Error loading targeted sub-item documents:");
        if (!stillLive()) return;
        // Safe fallback to legacy behavior.
        await loadAllSitesDocuments(false);
    }
};

const refreshRelevantDocuments = React.useCallback(() => {
    docsRequestedRef.current = true;
    setDocsLoading(true);
    getTaggeddocuments(props);
}, [props]);

useImperativeHandle(ref, () => ({
