    "&$expand=File,Author,Editor,SmartDocumentType,Portfolios,HHHH,Shareweb,Gruene,ILF,Gender,ALAKDigital" + "&$filter=FSObjType eq 0";
const filterPart = ` and (${idFilter})`;
const web = new Web(PropsArray?.siteUrl);
const query = queryBase.replace("$filter=FSObjType eq 0", `$filter=FSObjType eq 0${filterPart}`);
const data = await web.lists.getByTitle("Documents").items.select(query).get();
if (!stillLive()) {
    setDocsLoading(false);
