const uniqueData = data
    ?.filter((item: any, index: number, self: any[]) => index === self?.findIndex((x: any) => x?.Id === item?.Id))
    ?.filter((item: any) => includedTypes?.includes((item?.File_x0020_Type || "").toLowerCase()));
const matchedDocs = uniqueData?.map((item: any) => ({
    ...item,
    siteUrl: PropsArray?.AllListId?.siteUrl,
    CreatedDate: moment(item?.Created).format("DD/MM/YYYY"),
    ModifiedDate: moment(item?.Modified).format("DD/MM/YYYY"),
    AuthorImage: PropsArray?.Alltaskuser?.find((element: any) => element?.AssingedToUserId == item?.Author?.Id)?.Item_x0020_Cover?.Url,
    EditorImage: PropsArray?.Alltaskuser?.find((element: any) => element?.AssingedToUserId == item?.Editor?.Id)?.Item_x0020_Cover?.Url,
}));
const isLookupEmpty = (value: any) => {
    if (Array.isArray(value)) return value.length === 0;
    if (value && typeof value === 'object') return !(value?.Id !== undefined && value?.Id !== null && value?.Id !== '');
    return value === undefined || value === null || value === '';
};
// Same isolation as legacy HHHHQA: keep only docs that are
// portfolio-tagged and not also tagged to another site lookup.
let allRelevantDocs = matchedDocs?.filter((doc: any) =>
    isLookupEmpty(doc?.HHHH) &&
    isLookupEmpty(doc?.Shareweb) &&
    isLookupEmpty(doc?.Gruene ?? doc?.Grune) &&
    isLookupEmpty(doc?.ILF) &&
    isLookupEmpty(doc?.Gender) &&
    isLookupEmpty(doc?.ALAKDigital)
);
// Task/AWT-tagged docs belong in Relevant Sub-item Documents.
const siteTasksForAwt = (PropsArray?.AllSiteTasks || props?.AllSiteTasks || []).filter((task: any) =>
    !task?.siteUrl || task.siteUrl === PropsArray?.siteUrl
);
if (isPortfolioDocs && siteTasksForAwt.length > 0) {
    allRelevantDocs = allRelevantDocs?.filter((doc: any) =>
        !siteTasksForAwt.some((task: any) =>
            task?.SmartDocument?.some((sd: any) => sd?.Id === doc?.Id)
        )
    );
}

