export const GetServiceAndComponentAllData = async (Props?: any | null, filter?: any | null) => {
    if (!Props?.siteUrl) {
        return processGetServiceAndComponentAllDataCore(Props, filter);
    }
    const csfFilter = filter || DEFAULT_CSF_FILTER;
    // Include projectSelection in the key — picker vs portfolio paths differ.
    // "csf-pxc-processed" also busts older CSF-only caches that had empty ProjectData.
    const cacheKey = `${masterListSiteKey(Props.siteUrl)}::csf-pxc-processed::${csfFilter}::ps=${Props?.projectSelection === true ? "1" : "0"}`;
    const cached = masterListProcessedCache.get(cacheKey);
    if (cached && masterListFresh(cached.loadedAt)) {
        return cloneMasterList(cached.data);
    }
    let pending = masterListProcessedInFlight.get(cacheKey);
    if (!pending) {
        pending = processGetServiceAndComponentAllDataCore(Props, filter).then((data) => {
            if (data) {
                masterListProcessedCache.set(cacheKey, { data, loadedAt: Date.now() });
            }
            return data;
        }).finally(() => {
            masterListProcessedInFlight.delete(cacheKey);
        });
        masterListProcessedInFlight.set(cacheKey, pending);
    }
    return pending.then((data) => cloneMasterList(data));
};

export const GetServiceAndComponentAllDatasIndexDB = async (Props?: any | null, filter?: any | null) => {
    var ComponentsData: any = [];
    var AllPathGeneratedData: any = [];
    let AllPathGeneratedProjectdata: any = [];
    // let TaskUsers: any = [];
    let AllMasterTaskData: any = [];
    const deepCopy = (obj: any) => {
        return JSON.parse(JSON.stringify(obj));
    };
    try {
        let ProjectData: any = [];
        let web = new Web(Props.siteUrl);
        AllMasterTaskData = await getMasterdataFromIndexedDB();
        AllMasterTaskData = AllMasterTaskData?.filter((data: any) => data.siteUrl == Props?.siteUrl)
        const AllMasterTaskDataCopy = deepCopy(AllMasterTaskData);
        ProjectData = AllMasterTaskData.filter((projectItem: any) => projectItem.Item_x0020_Type === "Project" || projectItem.Item_x0020_Type === 'Sprint');
        AllMasterTaskData?.forEach((taggedComponent: any) => {
            taggedComponent.masterTaggedProject = []
            taggedComponent.joinedData = [];
            taggedComponent.ProjectTitle = ''
            taggedComponent.projectStructerId = ''
            ProjectData?.forEach((projectInfo: any) => {
                let projectData: any = { projectStructerId: '', ProjectTitle: '', ProjectId: '', joinedData: [], ProjectDeatil: {} }
                if (taggedComponent.Item_x0020_Type !== "Project" && taggedComponent.Item_x0020_Type !== 'Sprint' && projectInfo?.Portfolios?.some((tagComponent: any) => tagComponent?.Id === taggedComponent?.Id)) {
                    projectData.projectStructerId = projectInfo.PortfolioStructureID;
                    projectData.ProjectTitle = projectInfo?.Title != undefined ? projectInfo.Title : '';
                    taggedComponent.ProjectTitle = taggedComponent.ProjectTitle + `${taggedComponent?.ProjectTitle?.length > 0 ? ',' : ''}` + projectData.ProjectTitle
                    taggedComponent.projectStructerId = taggedComponent.projectStructerId + ',' + projectData.projectStructerId
                    projectData.ProjectId = projectInfo.Id;
                    projectData.ProjectDeatil = { ...projectInfo }
                    if (projectData?.projectStructerId && projectData?.ProjectTitle) {
                        projectData.joinedData.push(`Project ${projectData?.projectStructerId} - ${projectData.ProjectTitle != undefined ? projectData.ProjectTitle : ''}`)
                    }
                    taggedComponent.masterTaggedProject.push({ ...projectData })
                    //    
                }
            });
        });
        // console.log("all Service and Coponent data form global Call=======", AllMasterTaskData);
        // TaskUsers = await AllTaskUsers(Props.siteUrl, Props.TaskUserListId);
        $.each(AllMasterTaskData, function (index: any, result: any) {
            result.isSelected = false;
            result.siteUrl = Props?.siteUrl;
            result.siteName = Props.siteName;
            result["siteType"] = "Master Tasks";
            result.AllTeamName = "";
            result.listId = Props.MasterTaskListID;
            result.TaskID = result?.PortfolioStructureID;
            result.portfolioItemsSearch = result.Item_x0020_Type;
            result.isSelected = Props?.selectedItems?.find((obj: any) => obj.Id === result.ID);
            result.TeamLeaderUser = [];
            result.SmartPriority;

            result.DisplayDueDate = moment(result.DueDate).format("DD/MM/YYYY");
            result.DisplayCreateDate = moment(result.Created).format("DD/MM/YYYY");
            result.DueDate = moment(result.DueDate).format('DD/MM/YYYY')
            if (result.DueDate == 'Invalid date' || '') {
                result.DueDate = result.DueDate.replaceAll("Invalid date", "")
            }
            if (result.DisplayDueDate == "Invalid date" || "") {
                result.DisplayDueDate = result.DisplayDueDate.replaceAll(
                    "Invalid date",
                    ""
                );
            }
            if (result.DisplayCreateDate == "Invalid date" || "") {
                result.DisplayCreateDate = result.DisplayCreateDate.replaceAll(
                    "Invalid date",
                    ""
                );
            }
            // if (result.PercentComplete != undefined)
            //     result.PercentComplete = (result.PercentComplete * 100).toFixed(0);

            if (result.Short_x0020_Description_x0020_On != undefined) {
                result.Short_x0020_Description_x0020_On = result.Short_x0020_Description_x0020_On.replace(/(<([^>]+)>)/ig, '');
            }
            if (result.Item_x0020_Type === "Component") {
                result.boldRow = "boldClable";
                result.lableColor = "f-bg";
                result.ItemCat = "Portfolio"
            }
            if (result.Item_x0020_Type === "SubComponent") {
                result.lableColor = "a-bg";
                result.ItemCat = "Portfolio"
            }
            if (result.Item_x0020_Type === "Feature") {
                result.lableColor = "w-bg";
                result.ItemCat = "Portfolio"
            }
            if (result.Item_x0020_Type === "Project") {
                result.lableColor = "w-bg";
                result.ItemCat = "Project"
            }
            if (result.Item_x0020_Type === "Sprint") {
                result.ItemCat = "Project"
            }
            if (result.Item_x0020_Type === "Cycle") {
                result.ItemCat = "Project"
            }
            if (result?.Item_x0020_Type != undefined) {
                result.SiteIconTitle = result?.Item_x0020_Type=="Sprint"? "X": result?.Item_x0020_Type?.charAt(0);
            }

