const getPortfolioDataUptoFeatureLevel = (allItems: any[] = [], targetTitle: string = "Contact Database") => {
    const allowedTypes = new Set(["component", "subcomponent", "feature"]);
    const filteredItems = (allItems || []).filter((item: any) => {
        const itemType = (item?.Item_x0020_Type || "").toString().toLowerCase();
        return item?.TaskType === undefined && allowedTypes.has(itemType);
    });

    const childrenByParentId = new Map<any, any[]>();
    filteredItems.forEach((item: any) => {
        const parentId = item?.Parent?.Id;
        if (!childrenByParentId.has(parentId)) {
            childrenByParentId.set(parentId, []);
        }
        childrenByParentId.get(parentId).push(item);
    });

    const buildTree = (node: any): any => {
        const nodeCopy: any = { ...node };
        const itemType = (node?.Item_x0020_Type || "").toString().toLowerCase();
        if (itemType === "feature") {
            nodeCopy.subRows = [];
            return nodeCopy;
        }
        const children = childrenByParentId.get(node?.Id) || [];
        nodeCopy.subRows = children.map((child: any) => buildTree(child));
        return nodeCopy;
    };

    return filteredItems
        .filter((item: any) => (item?.Title || "").toString().toLowerCase() === targetTitle.toLowerCase())
        .map((item: any) => buildTree(item));
};
