const loadAllTasks = async (filters: any) => {
  if (seedBoundRef.current || hasSeededHierarchy()) {
    return;
  }
  let filteredData: any = [];
  await Promise.all(
    filters.map(async (f: any) => {
      const result = await globalCommon.getTaskFromIndexedDB(SelectedProp?.AllListId, f);
      if (result?.length > 0) {
        filteredData.push(...result);
      }
    })
  );
  if (filters?.length >= 1) {
    SelectedProp.allSiteTaks = filteredData;
    SelectedProp.AllTaskData = filteredData;
    AlltaskfilterData = filteredData
    if (AllDocumentDatas?.length > 0 && filteredData?.length > 0) {
      LoadAllSiteTasks();
      const refinedFilters = globalSubCommon.TaskswithPortfoliosfilters(filteredData);
      if (SelectedProp?.tableId !== "PortfolioProfile") {
        await loadAllDocuments(refinedFilters);
      }
      SelectedProp.AllMasterData = AllComponentsItems;
      SelectedProp.callbackDocument(AllDocumentDatas, filteredData, AllComponentsItems);
    } else {
      // setLoaded(true);
      AlltaskfilterData = SelectedProp?.allSiteTaks
      allTaskDataFlatLoadeViewBackup = filteredData;
      SelectedProp.callbackDocument(AllDocumentDatas, filteredData, AllComponentsItems);
      setData(filteredData);
      //DataPrepareForCSFAWT();
      setAllSiteTasksData(filteredData);

    }

  } else {
    setLoaded(true);
  }

