export const loadAllSiteTaskData = async (
    allListId?: any | null,
    filter?: any | null,
    pertiCularSites?: any | null,
    showOffShore?: any | undefined
) => {
    const tasksKey = JSON.stringify({
        s: allListId?.siteUrl || '',
        f: filter || '',
        p: pertiCularSites || null,
        o: showOffShore || false
    });

    const cachedTasks = siteTasksCache.get(tasksKey);
    if (cachedTasks) {
        return cloneTasks(cachedTasks.data);
    }
    const pendingTasks = siteTasksInFlight.get(tasksKey);
    if (pendingTasks) {
        return pendingTasks.then((d: any[]) => cloneTasks(d));
    }

    const tasksRequest = (async () => {
        const rows = await loadAllSiteTaskDataUncached(allListId, filter, pertiCularSites, showOffShore);
        if (rows && rows.length) {
            siteTasksCache.set(tasksKey, { data: rows, loadedAt: Date.now() });
        }
        return rows;
    })();
    siteTasksInFlight.set(tasksKey, tasksRequest);
    tasksRequest.then(
        () => siteTasksInFlight.delete(tasksKey),
        () => siteTasksInFlight.delete(tasksKey)
    );

    const fresh = await tasksRequest;
    return cloneTasks(fresh);
};

/**
 * Fetch tasks from an explicit list of site/list configs — one GET per unique
 * (siteUrl, listId, filter). Skips SmartMetadata "Sites" fan-out so callers
 * that already know their lists (e.g. OMT RootDashboardConfig) never reload
 * the same list twice via different hub entry points.
 */
export const loadTasksFromConfiguredLists = async (
    sites: any[] | null | undefined,
    filter?: any | null
) => {
    if (!sites?.length) return [];

    const seen = new Set<string>();
    const uniqueSites: any[] = [];
    for (const site of sites) {
        const listId = site?.listId;
        const siteUrl = resolveAbsoluteSiteUrl(
            site?.siteUrl?.Url || site?.siteUrl,
            site?.hubSiteUrl
        );
        if (!listId || !siteUrl) continue;

