const LoadAllSiteTasks = async function (isloading?: any) {
  if (!stillLive()) return;
  // Overview seed already bound the full tree — do not dump CSF or re-merge tasks.
  if (projectData?.__fromPxcSeed === true) {
    return;
  }
  if (isloading !== false) setPageLoader(true);
  CSFdata = [];
  let AllMasterData: any = await globalCommon.GetServiceAndComponentAllData(props?.props, `Item_x0020_Type eq 'Component' or Item_x0020_Type eq 'SubComponent' or Item_x0020_Type eq 'Feature'`)
  if (!stillLive()) return;
