      AllProjectTasks = AllSitesAllTasks?.filter((task: any) => task?.Project?.Id == projectData?.Id);
    } else {
      if (projectData?.subRows == undefined || projectData?.subRows?.length == 0) {
        AllProjectTasks = AllSitesAllTasks?.filter((task: any) => task.Project?.Id == projectData?.Id);
      }
      else if (projectData?.Item_x0020_Type == 'Project') {
        AllProjectTasks = AllSitesAllTasks?.filter((task: any) =>
          projectData?.subRows?.some((sprint: any) =>
            sprint?.Id == task?.Project?.Id ||
