import * as React from 'react';
import { useHistory } from 'react-router-dom';
import { buildSpaHref, navigateSpa } from '../HHHH-SP-Code/services/spaNavigation';
import { setPortfolioSeed } from '../HHHH-SP-Code/services/spaRowSeed';

export interface IPortfolioProfileNavLinkProps {
  /**
   * Full table row (parent + subRows). Preferred — Id taken from row.
   * Legacy: pass portfolioId only when row is unavailable.
   */
  portfolioRow?: any;
  portfolioId?: number | string | null | undefined;
  children: React.ReactNode;
  className?: string;
  title?: string;
  style?: React.CSSProperties;
}

function resolveNumericId(
  portfolioId: number | string | null | undefined,
  portfolioRow?: any
): number | null {
  const fromRow = portfolioRow?.Id ?? portfolioRow?.ID;
  const raw = fromRow ?? portfolioId;
  if (raw == null || raw === '') {
    return null;
  }
  const parsed = Number(raw);
  return !Number.isNaN(parsed) && parsed > 0 ? parsed : null;
}

/**
 * SPA link to Portfolio Profile.
 * Pass portfolioRow (row.original) so parent + children bind without reload.
 * URL still gets taskId for legacy readers — seed is the full row in memory.
 */
const PortfolioProfileNavLink: React.FC<IPortfolioProfileNavLinkProps> = ({
  portfolioId,
  portfolioRow,
  children,
  className,
  title,
  style
}) => {
  const history = useHistory();
  const id = resolveNumericId(portfolioId, portfolioRow);

  if (id == null) {
    return (
      <span className={className} style={style} title={title}>
        {children}
      </span>
    );
  }

  const params = { taskId: id };
  const href = buildSpaHref('/portfolio-profile', params);

  return (
    <a
      href={href}
      className={className}
      style={{ ...style, cursor: 'pointer' }}
      title={title}
      data-interception="off"
      data-spa-link="true"
      role="link"
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        if (portfolioRow) {
          setPortfolioSeed(id, portfolioRow);
        }
        navigateSpa(history, '/portfolio-profile', params);
      }}
    >
      {children}
    </a>
  );
};

export default PortfolioProfileNavLink;

