// URLs whose <img> fired onError - kept so a dead link collapses the box
// instead of leaving an empty bordered placeholder behind.
const [brokenImageUrls, setBrokenImageUrls] = useState<Record<string, boolean>>({});
const openImageInNewTab = (imageUrl: any) => {
  window.open(imageUrl, "_blank");
};
useEffect(() => {
  // Seed from Team Portfolio click — skip SmartMetadata Client Category
  // enrichment (only needed when we fetch the item by Id).
  const seedRow = getPortfolioSeed(ID || ComponentId);
  const hasSeed = !!(seedRow && seedMatchesId(seedRow, ID || ComponentId));
  parentFunctionCall();
  getPortFolioType();
  if (!hasSeed) {
    getSmartMetaDataListAllItems();
  }
}, []);
const handleMouseOver = (image: any) => {
  const imagename = getFileNameFromUrl(image)
  setcurrentImageName(imagename)
  setCurrentImage(image);
  setShowOverlay(true);
};

const handleMouseOut = () => {
  setShowOverlay(false);
};
const [OpenCategories, setOpenCategories] = useState(false)
const [Smartfeaturepopup, setSmartfeaturepopup] = React.useState(false);
const [portfolioTyped, setPortfolioTypeData] = useState<any>([]);
const [myparentData, setParentData] = useState([]);
const [hoveredId, setHoveredId] = useState(null);
const [isTooltipOpen, setIsTooltipOpen] = useState(false);
// PortfolioType
const handleDataFromChild = (data: any) => {
  setAllTask(data);
};
const handleMasterDataFromChild = (data: any) => {
  setAllMasterTaskData(data);
};
// Handle For the HHHH Project Management
// All props below are stable references (component state / the SelectedProp &
// TaskUser props / a shared EMPTY_ARRAY constant) rather than freshly-built
// object/array literals. This lets React.memo on PortfolioProjectManagement
// actually work, so the child only re-renders / re-fetches its project list
// when MyAllData (Dataimp), AllListId, or AllTaskUsers truly change - not on
// every unrelated parent re-render (hover, popup toggle, inline edit).
// NOTE: AllListId is passed as the full SelectedProp (a stable prop) instead of
// a reduced { siteUrl, MasterTaskListID } object, because the child forwards it
// to EditProjectPopup which also reads TaskUserListID / SmartMetadataListID.
const renderPortfolioProjectManagement = useCallback(() => {
  return (
    <PortfolioProjectManagement
      AllListId={SelectedProp}
      MyAllData={Dataimp}
      ContextValue={SelectedProp?.Context}
      AllTaskUsers={TaskUser || EMPTY_ARRAY}
      portfolioTypeDataItem={portfolioTyped || EMPTY_ARRAY}

