  const tryBindSelectedItemSeed = (): boolean => {
    const item = SelectedProp?.SelectedItem;
    // Seed/props path: item carries __fromPortfolioSeed and/or a subRows array
    // (empty [] = known leaf — still skip GetComponents). Query-string getById
    // rows have neither, so they fall through to cold load.
    const fromSeed =
      item &&
      (item.__fromPortfolioSeed === true ||
        item.__fromTaskSeed === true ||
        Array.isArray(item.subRows));
    if (!fromSeed) {
      return false;
    }
    // Portfolio Profile (CSFAWT) or task AWT table — bind hierarchy from navigation seed.
    if (
      SelectedProp?.tableId !== "PortfolioProfile" &&
      SelectedProp?.configration !== "CSFAWT" &&
      SelectedProp?.configration !== "AllAwt"
    ) {
      return false;
    }

    const rawSeededRows = Array.isArray(item.subRows) ? item.subRows : [];
    const seededRows =
      SelectedProp?.tableId === "PortfolioProfile" ||
        SelectedProp?.configration === "CSFAWT"
        ? organizeSeedRowsWithOthersFolder(rawSeededRows, item)
        : rawSeededRows;
    seedBoundRef.current = true;
    setData(seededRows);
    setLoaded(true);
    const flatMaster = flattenSeedTree({ ...item, subRows: seededRows });
    // Keep backups for export/filter — do NOT setAllMasterTasks (triggers DataPrepare / loader).
    allMasterTaskDataFlatLoadeViewBackup = flatMaster;
    allTaskDataFlatLoadeViewBackup = flatMaster.filter(
      (r: any) => r !== item && (r?.TaskType != null || r?.siteType !== "Master Tasks")
    );
    AlltaskfilterData = allTaskDataFlatLoadeViewBackup;
    allLoadeDataMasterTaskAndTask = flatMaster;

    if (SelectedProp?.onhandleUpdate) {
      SelectedProp.onhandleUpdate(flatMaster);
    }
    if (SelectedProp?.onDataUpdate) {
      SelectedProp.onDataUpdate(allTaskDataFlatLoadeViewBackup);
    }
    if (myContextData2?.setAllTableData) {
      myContextData2.setAllTableData([...seededRows]);
    }

    // Documents are deferred on Portfolio Profile — TaskDocuments loads on
    // accordion open. Task Profile already prefetches via updateResult.
    // Other tools still prefetch from the seeded tree.
    if (
      SelectedProp?.tableId !== "PortfolioProfile" &&
      SelectedProp?.tableId !== "TaskProfilegit"
    ) {
      try {
        const filtersportfoliodoc = globalSubCommon.PortfoliosfiltersQuery(
          flatMaster,
          "Portfolios/Id"
        );
        if (filtersportfoliodoc?.length > 0) {
          loadAllDocuments(filtersportfoliodoc);
        }
      } catch {
        // ignore doc seed path errors — profile header already bound
      }
    }
    return true;
  };

  const init = async () => {
    const seeded = tryBindSelectedItemSeed();
    // Guard: never start GetComponents / site-task getAll when seed tree exists.
    if (!seeded && !hasSeededHierarchy()) {
      if (SelectedProp?.configration == "AllCSF") {
        GetComponents();
      } else if (SelectedProp?.configration == "AllAwt") {
        LoadAllSiteTasks();
      } else {
        GetComponents();
      }
    } else if (!seeded && hasSeededHierarchy()) {
      // Race: SelectedItem arrived with subRows but bind did not run yet.
      tryBindSelectedItemSeed();
    }
    await findPortFolioIconsAndPortfolio();
    await getTaskType();
    // Prefer parent-provided reference data (Portfolio Profile Feature /
    // Portfoliop) to avoid duplicate TaskUsers + PortFolioType list reads.
    const preloadedUsers =
      SelectedProp?.AllTaskUsers ||
      SelectedProp?.TaskUsers ||
      SelectedProp?.TaskUser;
    if (SelectedProp?.portfolioTyped?.length > 0) {
      setPortfolioTypeData(SelectedProp.portfolioTyped);
    } else if (SelectedProp?.tableId !== "PortfolioProfile") {
      // Portfolio Profile's parent always loads PortFolioType and passes it;
      // wait via the adopt effect below instead of a duplicate list read.
      await getPortFolioTypeOnly();
    }
    const parentSuppliedUsers =
      SelectedProp?.AllTaskUsers !== undefined ||
      SelectedProp?.TaskUsers !== undefined ||
      SelectedProp?.TaskUser !== undefined;
    if (Array.isArray(preloadedUsers) && preloadedUsers.length > 0) {
      const filtered = preloadedUsers.filter((user: any) => {
        const groupTitle = (user?.UserGroup?.Title || user?.userGroup?.Title)?.toLowerCase();
        return groupTitle !== "ex staff" && groupTitle !== "ex-staff";
      });
      Response = filtered;
      TaskUsers = filtered;
      setTaskUser(filtered);
    } else if (!parentSuppliedUsers) {
      await getTaskUsers();
    }
    // Seeded Portfolio Profile: lighter SmartMetadata (Sites/filters only),
    // not the full $top=4999 dump used by cold GetComponents loads.
    if (!SelectedProp?.skipSmartMetadata) {
      GetSmartmetadata({ light: seeded || hasSeededHierarchy() });
    }
    adminPermision();

  };

  init();
}, [tableReloadKey]);

