if (smartDocIds.size > 0) {
    idClauses.push(...Array.from(smartDocIds).map((id) => `Id eq ${id}`));
}
if (childPortfolioIds.size > 0) {
    idClauses.push(...Array.from(childPortfolioIds).map((id) => `Portfolios/Id eq ${id}`));
}

if (idClauses.length === 0) {
    AllDocumentDataRef.current = [];
    filterTagDoc();
    return;
}

const web = new Web(props?.siteUrl);
const queryBase = "Id,Title,PriorityRank,Year,Body,Item_x0020_Cover,Portfolios/Id,Portfolios/Title,Portfolios/PortfolioStructureID,Portfolios/ItemType,File_x0020_Type,FileLeafRef,FileDirRef,ItemRank,ItemType,Url,Created,Modified,Author/Id,Author/Title,Editor/Id,Editor/Title,SmartDocumentType/Id,SmartDocumentType/Title,EncodedAbsUrl,File/Length,HHHH/Id,HHHH/Title,Shareweb/Id,Gruene/Id,ILF/Id,Gender/Id,ALAKDigital/Id&$expand=File,Author,Editor,SmartDocumentType,Portfolios,HHHH,Shareweb,Gruene,ILF,Gender,ALAKDigital";
const chunkSize = 20;
const chunks: string[][] = [];
for (let i = 0; i < idClauses.length; i += chunkSize) {
    chunks.push(idClauses.slice(i, i + chunkSize));
}
// Chunks are independent id/portfolio lookups (order doesn't matter — results
// get deduped and re-sorted downstream), so run them concurrently instead of
// one-at-a-time. With >20 tagged ids this cuts wait time from N round trips to 1.
const pages = await Promise.all(
    chunks.map((chunk) => {
        const filter = `FSObjType eq 0 and (${chunk.join(" or ")})`;
        return web.lists.getByTitle("Documents").items.select(queryBase).filter(filter).getAll();
    })
);
if (!stillLive()) return;
const docs: any[] = pages.flat().filter(Boolean);

if (!stillLive()) return;

// No includedTypes check here: the REST filter above already scoped this fetch to
// exactly the tagged doc IDs / child-portfolio IDs (legacy HHHHQA's "isExplicitlyTagged"
// bypass) — re-applying a type allowlist on top would drop legitimately tagged docs
// whose extension isn't in that list (e.g. images, notes, csv).
const uniqueDocs = (docs || [])

