      const img = imgTags[i];
      const src = img.getAttribute("src");

      if (src && src.indexOf("data:image") === 0) {
        // convert base64 to File
        const file = base64ToFile(src, `editor-img-${Date.now()}.png`);

        // upload to SharePoint
