const Call = React.useCallback(async (item1: any, type?: any) => {
    if (type === 'close' || type === 'Close' || !item1 || item1 === 'close' || item1 === 'Close') {
        setIsComponent(false);
        showProgressHide();
        return;
    }
    // Local tree + session cache — never GetMasterData (stale cache / blank / throttle).
    const id = rowChangeId(item1) || Number(item1?.Id ?? item1?.ID);
    const siteType = item1?.siteType || 'Master Tasks';
    if (type === 'deletePXC' && id) {
        AllProject = removeRowFromTree(AllProject, id, siteType);
        AllProjectDataWithAWT = removeRowFromTree(AllProjectDataWithAWT, id, siteType);
        setFlatData(showAllAWTGrouped ? AllProjectDataWithAWT : AllProject);
        notifyRowChange({
            action: 'delete',
            list: 'MasterTasks',
            id,
            siteType,
            listId: item1?.listId || AllListId?.MasterTaskListID,
            source: 'pxc-overview',
        });
    } else if (id) {
        const row = { ...item1, siteType, listId: item1?.listId || AllListId?.MasterTaskListID };
        const merged =
            mergeRowIntoTree(AllProject, row) ||
            insertMasterRowIntoTree(AllProject, row);
        mergeRowIntoTree(AllProjectDataWithAWT, row) ||
            insertMasterRowIntoTree(AllProjectDataWithAWT, row);
        if (merged || AllProject?.length) {
            setFlatData(showAllAWTGrouped ? [...AllProjectDataWithAWT] : [...AllProject]);
        }
        notifyRowChange({
            action: type === 'EditPopup' ? 'update' : 'update',
            list: 'MasterTasks',
            id,
            siteType,
            listId: row.listId,
            row,
            source: 'pxc-overview',
        });
    }
    setIsComponent(false);
    showProgressHide();
}, [showAllAWTGrouped]);
