/**
 * Cross-page SPA row sync (keep-alive tables).
 * Write → patch session caches (no SharePoint refetch) → notify listeners.
 * Cleared only on full page reload with the rest of the module Maps.
 */

export type SpaRowChangeAction = 'add' | 'update' | 'delete' | 'restructure';
export type SpaRowChangeList = 'MasterTasks' | 'SiteTasks';

export interface SpaRowChange {
  action: SpaRowChangeAction;
  list: SpaRowChangeList;
  id: number;
  /** Master Tasks | site title (HHHH, etc.) */
  siteType?: string;
  listId?: string | number;
  row?: any;
  /** Skip re-applying on the page that already patched its UI. */
  source?: string;
  /** Restructure: PlannedWrite[] for applyRestructurePlanToTree on listeners. */
  writes?: any[];
  /** Restructure fallback: patched row payloads. */
  rows?: any[];
}

type Listener = (change: SpaRowChange) => void;
type CacheApplier = (change: SpaRowChange) => void;

const listeners = new Set<Listener>();
let cacheApplier: CacheApplier | null = null;

/** globalCommon registers this once so we avoid circular imports. */
export const registerSessionRowChangeApplier = (fn: CacheApplier): void => {
  cacheApplier = fn;
};

/** Infer Master vs site task from a row. */
export const inferRowList = (row: any): SpaRowChangeList => {
  const itemType = row?.Item_x0020_Type;
  if (
    itemType === 'Project' ||
    itemType === 'Sprint' ||
    itemType === 'Cycle' ||
    itemType === 'Component' ||
    itemType === 'SubComponent' ||
    itemType === 'Feature'
  ) {
    return 'MasterTasks';
  }
  const site = String(row?.siteType || row?.siteName || row?.listName || '');
  if (site === 'Master Tasks' || /master\s*tasks/i.test(site)) {
    return 'MasterTasks';
  }
  if (row?.TaskType != null || row?.TaskTypeId != null) {
    return 'SiteTasks';
  }
  return 'MasterTasks';
};

export const rowChangeId = (row: any): number => {
  const n = Number(row?.Id ?? row?.ID);
  return Number.isFinite(n) && n > 0 ? n : 0;
};

const isBlankPct = (v: any): boolean =>
  v === undefined ||
  v === null ||
  v === '' ||
  (typeof v === 'number' && Number.isNaN(v)) ||
  (typeof v === 'string' && (v.trim() === '' || v.toLowerCase() === 'nan'));

/**
 * Safe field merge for keep-alive trees:
 * - never wipe existing subRows unless incoming explicitly provides an array
 * - never overwrite PercentComplete with blank/NaN (fixes Profile → TP NaN)
 */
export const safeMergeRow = (existing: any, incoming: any): any => {
  if (!existing) return incoming ? { ...incoming } : existing;
  if (!incoming) return existing;
  const next = { ...existing, ...incoming };
  if (!Array.isArray(incoming.subRows) || incoming.subRows.length === 0) {
    next.subRows = existing.subRows;
  }
  if (isBlankPct(incoming.PercentComplete) && !isBlankPct(existing.PercentComplete)) {
    next.PercentComplete = existing.PercentComplete;
  }
  if (
    isBlankPct(incoming.percentCompleteValue) &&
    !isBlankPct(existing.percentCompleteValue)
  ) {
    next.percentCompleteValue = existing.percentCompleteValue;
  }
  return next;
};

