/** Convenience emit used by popups / tables. */
export const emitRowChange = (
  action: SpaRowChangeAction,
  row: any,
  extras?: {
    source?: string;
    list?: SpaRowChangeList;
    siteType?: string;
    listId?: string | number;
  }
): void => {
  const id = rowChangeId(row) || Number(row?.Id ?? row?.ID);
  if (!id && action !== 'restructure') return;
  notifyRowChange({
    action,
    list: extras?.list || inferRowList(row),
    id: id || 0,
    siteType: extras?.siteType || row?.siteType || row?.siteName,
    listId: extras?.listId || row?.listId,
    row: action === 'delete' ? undefined : row,
    source: extras?.source,
  });
};

/**
 * After shared restructure succeeds — patch session caches per write, then
 * notify keep-alive pages with the PlannedWrite[] so they can
 * applyRestructurePlanToTree (no GetMasterData).
 */
export const notifyRestructureWrites = (
  writes: any[],
  source: string
): void => {
  if (!Array.isArray(writes) || writes.length === 0) return;
  writes.forEach((w: any) => {
    const id = Number(w?.itemId);
    if (!id) return;
    const fields = w?.fields || {};
    const list: SpaRowChangeList = w?.family === 'AWT' ? 'SiteTasks' : 'MasterTasks';
    const row: any = {
      Id: id,
      ID: id,
      listId: w?.listId,
      Title: w?.title,
      ...fields,
    };
    if (Object.prototype.hasOwnProperty.call(fields, 'ParentId')) {
      const pid = fields.ParentId as number | null;
      row.ParentId = pid;
      row.Parent = pid != null ? { Id: pid } : null;
    }
    if (Object.prototype.hasOwnProperty.call(fields, 'ParentTaskId')) {
      const pid = fields.ParentTaskId as number | null;
      row.ParentTaskId = pid;
      row.ParentTask = pid != null ? { Id: pid } : null;
    }
    try {
      cacheApplier?.({
        action: 'update',
        list,
        id,
        listId: w?.listId,
        siteType: list === 'MasterTasks' ? 'Master Tasks' : undefined,
        row,
      });
    } catch {
      /* ignore */
    }
  });
  const first = writes[0];
  const batch: SpaRowChange = {
    action: 'restructure',
    list: first?.family === 'AWT' ? 'SiteTasks' : 'MasterTasks',
    id: Number(first?.itemId) || 0,
    writes,
    source,
  };
  listeners.forEach((fn) => {
    try {
      fn(batch);
    } catch {
      /* ignore */
    }
  });
};

/**
 * Patch in-memory Master / site-task session stores, then notify keep-alive pages.
 * Never hits SharePoint — safe for throttle / blank-page avoidance.
 */
export const notifyRowChange = (change: SpaRowChange): void => {
  if (change?.action === 'restructure') {
    if (Array.isArray(change.writes) && change.writes.length) {
      notifyRestructureWrites(change.writes, change.source || 'restructure');
      return;
    }
    if (Array.isArray(change.rows)) {
      change.rows.forEach((row: any) => {
        const id = rowChangeId(row);
        if (!id) return;
        notifyRowChange({
          action: 'update',
          list: change.list || inferRowList(row),
          id,
          siteType: row?.siteType || row?.siteName || change.siteType,
          listId: row?.listId || change.listId,
          row,
          source: change.source,
        });
      });
      return;
    }
  }
  const id = Number(change?.id);
  if (!id || Number.isNaN(id)) {
    return;
  }
  const normalized: SpaRowChange = {
    ...change,
    id,
    list: change.list || 'MasterTasks',
    action: change.action,
  };
  try {
    cacheApplier?.(normalized);
  } catch {
    // Cache patch failed — still notify UI listeners with the row payload.
  }
  listeners.forEach((fn) => {
    try {
      fn(normalized);
    } catch {
      // A failing listener must not block others.
    }
  });
};

export const subscribeRowChange = (fn: Listener): (() => void) => {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
};

