const Call = async (propsItems: any, type: any) => {
  if (type === "close" || type === "Close" || propsItems === "Close" || propsItems === "close" || !propsItems) {
    setCheckedList({});
    setIsComponent(false);
    setIsOpenActivity(false);
    setIsOpenWorkstream(false);
    setActivityPopup(false);
    return;
  }
  if (type != "deletePXC") {
    if (propsItems?.Id != undefined) {
      if (propsItems?.DueDate != undefined) {
        propsItems.DisplayDueDate = propsItems.DueDate != null
