const CallBack = React.useCallback(async (item: any, type: any) => {
  setIsAddStructureOpen(false)
  if (type == 'Save') {
    if (item?.Item_x0020_Type == "Project" || item?.Item_x0020_Type == "Sprint" || item?.Item_x0020_Type == "Cycle") {
      // let allData = data;
      if (CurrentUserData?.Id != undefined) {
        item.createdImg = CurrentUserData?.Item_x0020_Cover?.Url
