        item.DisplayModifiedDate = Moment(new Date()).format("DD/MM/YYYY")
        item.Author = CurrentUserData
        item.TaskID = item.PortfolioStructureID;
      }
      if ((selectedItem == undefined || (Object.keys(selectedItem).length == 0)) && (projectData?.Item_x0020_Type == 'Project' || projectData?.Item_x0020_Type == 'Sprint')) {
        let itemData: any = JSON.parse(JSON.stringify(item));
        itemData.subRows = [];
        item.uniqueID = backupMasterTaskData.length + 1;
        backupMasterTaskData.push(item)
        allBackupSprintAndTask.push(item)
        renderData = [];
        renderData = renderData.concat(allBackupSprintAndTask)
        refreshData();
        countPoject(allBackupSprintAndTask);
      }
      if ((Object.keys(selectedItem).length > 0) && selectedItem?.Item_x0020_Type == 'Sprint') {
        item.uniqueID = backupMasterTaskData.length + 1;
