      setisOpenEditPopup(false);
      const edited: any = passdata;
      const row = item?.data || item;
      const id = rowChangeId(row) || rowChangeId(edited);
      if (id && row && typeof row === 'object') {
        const normalized = {
          ...row,
          Id: row?.Id ?? row?.ID ?? id,
          siteType: row?.siteType || edited?.siteType,
          listId: row?.listId || edited?.listId,
