          list: inferRowList(normalized),
          id,
          siteType: normalized.siteType,
          listId: normalized.listId,
          row: normalized,
          source: 'pxc-profile',
        });
      }
    }
    if (item == "Delete-Task" || item === "Delete") {
      const row: any = passdata;
