import * as React from 'react';
import { useHistory } from 'react-router-dom';
import { buildSpaHref, navigateSpa } from '../HHHH-SP-Code/services/spaNavigation';
import { setPxcSeed } from '../HHHH-SP-Code/services/spaRowSeed';

export interface IPxcProfileNavLinkProps {
  /**
   * Full table / project row (parent + subRows when available). Preferred.
   * Legacy: pass projectId only when row is unavailable.
   */
  projectRow?: any;
  projectId?: number | string | null | undefined;
  children: React.ReactNode;
  className?: string;
  title?: string;
  style?: React.CSSProperties;
}

function resolveNumericProjectId(
  projectId: number | string | null | undefined,
  projectRow?: any
): number | null {
  const fromRow =
    projectRow?.Id ??
    projectRow?.ID ??
    projectRow?.ProjectId ??
    projectRow?.Project?.Id;
  const raw = fromRow ?? projectId;
  if (raw == null || raw === '') {
    return null;
  }
  const parsed = Number(raw);
  return !Number.isNaN(parsed) && parsed > 0 ? parsed : null;
}

function isSeedablePxcRow(row: any): boolean {
  return (
    !!row &&
    (Array.isArray(row.subRows) ||
      row.Item_x0020_Type === 'Project' ||
      row.Item_x0020_Type === 'Sprint' ||
      row.Item_x0020_Type === 'Cycle')
  );
}

/**
 * SPA link to PXC Profile.
 * Pass projectRow (row.original or Project object) — do not invent ID-only stubs.
 */
const PxcProfileNavLink: React.FC<IPxcProfileNavLinkProps> = ({
  projectId,
  projectRow,
  children,
  className,
  title,
  style
}) => {
  const history = useHistory();
  const id = resolveNumericProjectId(projectId, projectRow);

  if (id == null) {
    return (
      <span className={className} style={style} title={title}>
        {children}
      </span>
    );
  }

  const params = { ProjectId: id };
  const href = buildSpaHref('/pxc-profile', params);

  return (
    <a
      href={href}
      className={className}
      style={{ ...style, cursor: 'pointer' }}
      title={title}
      data-interception="off"
      data-spa-link="true"
      role="link"
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        if (isSeedablePxcRow(projectRow)) {
          setPxcSeed(id, projectRow);
        }
        navigateSpa(history, '/pxc-profile', params);
      }}
    >
      {children}
    </a>
  );
};

export default PxcProfileNavLink;

