const GetMasterData = async (loadtask: any) => {
  if (!stillLive()) return;
  if (QueryId == null || QueryId === '' || QueryId === 'null' || QueryId === 'undefined' || isNaN(Number(QueryId))) {
    setPageLoader(false);
    return;
  }
  let pxData: any = [];
  loadAllflatPXC = [];
  setPageLoader(true);

  // In-memory seed from table click — show header immediately (no sessionStorage).
  const pxcSeed = getPxcSeed(QueryId);
  const hasPxcSeed = !!(pxcSeed && seedMatchesId(pxcSeed, QueryId));
  if (hasPxcSeed) {
    if (!stillLive()) return;
    setMasterdata({
      ...pxcSeed,
      Id: pxcSeed.Id ?? pxcSeed.ID ?? Number(QueryId),
      ID: pxcSeed.ID ?? pxcSeed.Id ?? Number(QueryId),
      siteUrl: pxcSeed.siteUrl || props?.siteUrl,
      listId: pxcSeed.listId || AllListId?.MasterTaskListID,
      TaskID: pxcSeed.TaskID || pxcSeed.PortfolioStructureID,
    });
  }

  let web = new Web(props?.siteUrl);
  let projectItem: any;
  // Was: this project item was always re-fetched here even when the exact
  // row was already sitting in memory from PXC Overview / Team Portfolio
  // (which both source their rows from GetPXCData, the same shape this
  // fetch's own downstream processing already tolerates). Mirrors the
  // guard Portfolio Profile uses for the same reason. Child data — the
  // Activities/Sprints/Cycles under this project — is NOT part of this
  // fetch; it comes from the separate GetPXCData/GetServiceAndComponentAllData
  // calls further down, which always run regardless of the seed.
  if (hasPxcSeed) {
    projectItem = {
      AssignedTo: [],
      TeamMembers: [],
      TaskCategories: [],
      Portfolios: [],
      ...pxcSeed
    };
  } else {
    projectItem = await web.lists
      .getById(AllListId?.MasterTaskListID)
      .items.select("ComponentCategory/Id", "ComponentLink", "ComponentCategory/Title", "DueDate", "SiteCompositionSettings", "PortfolioStructureID", "PortfoliosId", "Portfolios/Id", "Portfolios/Title", "SmartDocument/Id", "SmartDocument/Title", "ItemRank", "ShortDescriptionVerified", "Portfolio_x0020_Type", "BackgroundVerified", "descriptionVerified", "Synonyms", "BasicImageInfo", "DeliverableSynonyms", "OffshoreComments", "OffshoreImageUrl", "HelpInformationVerified", "IdeaVerified", "TechnicalExplanationsVerified", "Deliverables", "DeliverablesVerified", "ValueAddedVerified", "CompletedDate", "Idea", "ValueAdded", "TechnicalExplanations", "Item_x0020_Type", "Sitestagging", "Package", "Parent/Id", "Parent/Title", "Short_x0020_Description_x0020_On", "Short_x0020_Description_x0020__x", "Short_x0020_description_x0020__x0", "AdminNotes", "AdminStatus", "Background", "Help_x0020_Information", "TaskCategories/Id", "TaskCategories/Title", "PriorityRank", "Reference_x0020_Item_x0020_Json", "TeamMembers/Title", "TeamMembers/Name", "TeamMembers/Id", "Item_x002d_Image", "ComponentLink", "IsTodaysTask", "AssignedTo/Title", "AssignedTo/Name", "AssignedTo/Id", "AttachmentFiles/FileName", "FileLeafRef", "FeedBack", "Title", "Id", "Company", "StartDate", "DueDate", "Comments", "Categories", "Status", "WebpartId", "Body", "Mileage", "PercentComplete", "WorkingAction", "Attachments", "Priority", "Created", "Modified", "Author/Id", "Author/Title", "Editor/Id", "Editor/Title", "ClientCategory/Id", "ClientCategory/Title", "TeamsGroup")
      .expand("ClientCategory", "ComponentCategory", "AssignedTo", "AttachmentFiles", "SmartDocument", "Author", "Editor", "TeamMembers", "Portfolios", "TaskCategories", "Parent")
      .getById(QueryId).get().catch((error: any) => {
        if (isAbortError(error) || !stillLive()) return;
        setPageLoader(false)
      })
  }
  if (!stillLive()) return;
  if (!projectItem) return;
