const flattenPxcSeedTree = (root: any): any[] => {
  const out: any[] = [];
  const walk = (node: any) => {
    if (!node) return;
    out.push(node);
    (Array.isArray(node.subRows) ? node.subRows : []).forEach(walk);
  };
  walk(root);
  return out;
};

if (canUsePxcSeedTree) {
  projectItem.__fromPxcSeed = true;
  if (!Array.isArray(projectItem.subRows)) {
    projectItem.subRows = [];
  }
  AllFlatProject = flattenPxcSeedTree(projectItem);
  AllMasterTasks = AllFlatProject;
